    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # The repeated horizontal stripe is the ordered palette for a vertical
    # stack of copies of the nearby silhouette.
    keys = []
    for r in range(h):
        cols = [c for c, value in enumerate(grid[r]) if value != 0]
        if not cols or cols != list(range(cols[0], cols[-1] + 1)):
            continue
        palette = grid[r][cols[0]:cols[-1] + 1]
        if len(palette) < 3:
            continue
        rows = [rr for rr in range(h)
                if grid[rr][cols[0]:cols[0] + len(palette)] == palette]
        if len(rows) >= 2:
            keys.append((len(palette), palette, cols[0], rows))
    if not keys:
        return out
    _, palette, start, key_rows = max(keys, key=lambda item: item[0])
    n = len(palette)
    key_pixels = {(r, c) for r in key_rows for c in range(start, start + n)}

    # Record each color's full silhouette (the template objects are separated
    # from the repeated palette stripe).
    masks = {}
    for color in set(palette):
        cells = [(r, c) for r in range(h) for c in range(w)
                 if grid[r][c] == color and (r, c) not in key_pixels]
        if cells:
            masks[color] = cells

    mid = n // 2
    def draw(mask, source_index, target_index, color):
        top = min(r for r, c in mask)
        bottom = max(r for r, c in mask)
        step = bottom - top + 1
        shift = (target_index - source_index) * step
        for r, c in mask:
            rr = r + shift
            if 0 <= rr < h and 0 <= c < w:
                out[rr][c] = color

    if n % 2:
        # The single middle layer is the template for the whole stack.
        source_color = palette[mid]
        if source_color in masks:
            for i, color in enumerate(palette):
                draw(masks[source_color], mid, i, color)
    else:
        # The two central layers are the available templates; extend each
        # outward from its own side of the stack.
        for i in range(n):
            if i < mid:
                source_index = mid - 1
            elif i > mid:
                source_index = mid
            else:
                continue
            source_color = palette[source_index]
            if source_color in masks:
                draw(masks[source_color], source_index, i, palette[i])

    # The palette stripe is an instruction, not part of the final picture.
    for r, c in key_pixels:
        out[r][c] = 0
    return out
